INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.87.0',
  '2026-09-16',
  'Пульт ТВ: продолжить просмотр',
  E'На главной медиатеки на приставке первым разделом — «Продолжить просмотр»: где вы остановились в каждом сериале и фильме, свежие первыми. На плитке видно серию («S02 · E05»), сколько осталось и полоску просмотренного. Нажали — плеер откроет ту же серию и поставит на пять секунд раньше места, где прервались, дальше серии идут как обычно, сезон за сезоном.\n\nДосмотрели серию — в списке сразу следующая, в том числе первая серия нового сезона. Досмотрели сериал или фильм — он из списка пропадает. Случайно включили другую серию на полминуты — место в сериале не сбивается. Ненужное можно убрать крестиком.\n\nНа экране сериала первой стоит кнопка «▶ Продолжить», и он открывается на том сезоне, где остановились. Позиции хранятся на домашнем компьютере с медиатекой, а не в браузере приставки, — не пропадут при очистке браузера.',
  E'Агент: progress.go, GET/PUT/POST/DELETE /api/progress, хранение в progress.json кэша (атомарная запись, до 20 записей, старше 180 дней выбрасываются). Плеер шлёт id файла, позицию и длительность раз в 15 с, на паузе, при выходе из плеера, при переключении серии и в конце серии (позиция = длительность); при закрытии страницы — sendBeacon (поэтому POST). Ключ записи — id плитки каталога: агент выводит сериал или фильм из раскладки папок так же, как catalog.go. Досмотрено — осталось < 2 мин или ≥ 97% (у роликов короче 5 минут только 97%) — запись переходит на следующую серию с нуля, через сезон тоже; мини-сериал за свою папку не выходит. Позиция меньше минуты не создаёт запись и не перезаписывает чужую серию, но свою обновляет.\n\nПосле перекодирования id файла меняется (хеш пути): запись хранит путь внутри сериала без расширения и находит .mp4 вместо .avi — к этой ночи, когда перекодируется The Big Bang Theory. Пути наружу не отдаются.\n\nГрабли, найденные в браузере: «✕ Убрать» откатывалось — убранный фильм оставался загруженным на паузе, и отправка позиции при закрытии страницы создавала запись заново. Теперь sendBeacon молчит на паузе (позиция уже сохранена), а убранный файл не записывается, пока его снова не запустят. До перемотки на сохранённое место позиция не шлётся, чтобы не затереть её нулём.\n\nПроверено: progress_test.go (сезон за сезоном, фильм в корне и в папке, мини-сериал, перекодирование, отсутствие путей в ответе) и в браузере — запись при выходе из плеера, раздел на главной, кнопка на экране сериала, перемотка на 5 с раньше, переход на следующую серию после досмотренной, две позиции разом, «Убрать» с перезагрузкой страницы.'
);
